{
  "name": "FirebaseCoreInternal",
  "version": "12.19.0",
  "summary": "APIs for internal FirebaseCore usage.",
  "description": "Not for public use.\nCommon APIs for internal FirebaseCore usage.",
  "homepage": "https://firebase.google.com",
  "license": {
    "type": "Apache-2.0",
    "file": "LICENSE"
  },
  "authors": "Google, Inc.",
  "source": {
    "git": "https://github.com/firebase/firebase-ios-sdk.git",
    "tag": "CocoaPods-12.19.0"
  },
  "social_media_url": "https://twitter.com/Firebase",
  "platforms": {
    "ios": "15.0",
    "osx": "10.15",
    "tvos": "15.0",
    "watchos": "7.0"
  },
  "source_files": [
    "FirebaseCore/Internal/Sources/**/*.swift"
  ],
  "resource_bundles": {
    "FirebaseCoreInternal_Privacy": "FirebaseCore/Internal/Sources/Resources/PrivacyInfo.xcprivacy"
  },
  "swift_versions": "5.9",
  "dependencies": {
    "GoogleUtilities/NSData+zlib": [
      "~> 8.1"
    ]
  },
  "testspecs": [
    {
      "name": "Unit",
      "test_type": "unit",
      "scheme": {
        "code_coverage": true
      },
      "platforms": {
        "ios": "15.0",
        "osx": "10.15",
        "tvos": "15.0"
      },
      "source_files": [
        "FirebaseCore/Internal/Tests/Unit/**/*.swift",
        "FirebaseCore/Internal/Tests/Common/**/*.swift"
      ],
      "requires_app_host": true
    },
    {
      "name": "Integration",
      "test_type": "unit",
      "scheme": {
        "code_coverage": true
      },
      "platforms": {
        "ios": "15.0",
        "osx": "10.15",
        "tvos": "15.0"
      },
      "source_files": [
        "FirebaseCore/Internal/Tests/Integration/**/*.swift",
        "FirebaseCore/Internal/Tests/Common/**/*.swift"
      ],
      "requires_app_host": true
    }
  ],
  "swift_version": "5.9"
}
